fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // a = total distance between start and end
    // b = fuel capacity
    // f = fuel station position from start (0 < f < a)
    // k = number of full journeys (back and forth)

    // Impossibility checks first:
    // Capacity must be at least enough to reach the station from start
    if b < f {
        return -1;
    }
    // Capacity must be at least enough to reach the far endpoint from station
    if b < a - f {
        return -1;
    }
    // If more than one journey, capacity must be enough to do a full round segment:
    // (twice the total distance - station's position) as per problem statement
    if k > 1 && b < 2 * a - f {
        return -1;
    }
    // Special case when k == 1 and capacity less than both total distance and station distance -> impossible
    if k == 1 && b < a && b < f {
        return -1;
    }

    // If only one journey
    if k == 1 {
        // If capacity >= total distance => no refueling needed
        if b >= a {
            return 0;
        }
        // Otherwise, capacity < total distance but >= station distance => refuel needed once
        // This is guaranteed feasible because we passed the conditions above
        return 1;
    }

    // For k > 1 journeys:
    // Because of previous bounds, the capacity is sufficient for station reachability,
    // far endpoint reachability from station, and (2 * a - f) bound.

    // The question reduces to:
    // - Is refueling needed (1)
    // - Or is the capacity enough so no refueling is needed at all (0)
    // As b < a (otherwise would have returned 0 from the single journey case),
    // refuel is definitely needed.

    // But let's confirm: If capacity >= a, no refuel needed
    // (But the above if for k==1 handles that case already, so k>1 and capacity >= a means no refuel needed)
    if b >= a {
        return 0;
    }

    // Otherwise, refuel needed during the journeys, so return 1
    return 1;
}